const items = $input.all();
if (!items || items.length === 0) return [];

return items.map((itemObj) => {
  const item = itemObj.json;
  const id = item.id || item.ts || `slack-${Date.now()}`;
  const title = item.title || item.channel_name || 'Slack Message';
  const sender = item.user_name || item.sender || 'Slack User';
  const originalContent = item.text || item.message || title;
  const eventCreatedAt = item.ts
    ? new Date(parseFloat(item.ts) * 1000).toISOString()
    : new Date().toISOString();
  const sourceUrl = item.permalink || 'https://slack.com';

  return {
    json: {
      externalId: id,
      title,
      sender,
      originalContent,
      eventCreatedAt,
      sourceUrl
    }
  };
});

