parameters.jsCode:
const msg = $('Normalize Slack Message').first().json;
let summary = 'Slack message received.';

try {
  const input = $input.first().json;
  const text = input.text || input.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (text) {
    const cleaned = text.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    summary = parsed.summary || text;
  }
} catch (e) {
  summary = msg.originalContent.slice(0, 150) + '...';
}

return [{
  json: {
    source: 'slack',
    activity_type: 'message',
    external_id: msg.externalId,
    title: msg.title,
    sender: msg.sender,
    summary,
    original_content: msg.originalContent,
    source_url: msg.sourceUrl,
    event_created_at: msg.eventCreatedAt,
    metadata: { channel: msg.title }
  }
}];
